// Ported from the Node app's Sequelize model PurchaseOrderLine (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class PurchaseOrderLineConfiguration : IEntityTypeConfiguration<PurchaseOrderLine>
{
    public void Configure(EntityTypeBuilder<PurchaseOrderLine> builder)
    {
        builder.ToTable("purchase_order_lines");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.OrderId).HasColumnName("order_id");
        builder.Property(e => e.ItemId).HasColumnName("item_id");
        builder.Property(e => e.Quantity).HasColumnName("quantity");
        builder.Property(e => e.UnitCost).HasColumnName("unit_cost").HasColumnType("decimal(10,2)").HasDefaultValueSql("0");
        builder.HasOne(e => e.PurchaseOrder).WithMany(p => p.PurchaseOrderLines).HasForeignKey(e => e.OrderId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.InventoryItem).WithMany(p => p.PurchaseOrderLines).HasForeignKey(e => e.ItemId).OnDelete(DeleteBehavior.NoAction);
    }
}
